Suggestion: implement focus trap. A concrete suggestion:

```svelte
  // Trap Tab inside the dialog and restore focus to the previously focused
  // element when the tour unmounts.
  function trapFocus(node: HTMLElement) {
    const previouslyFocused = document.activeElement as HTMLElement | null;
    node.focus();
    const onKeydown = (e: KeyboardEvent) => {
      if (e.key !== "Tab") return;
      const focusables = node.querySelectorAll<HTMLElement>(
        'button:not([disabled]), [href], input, select, textarea, [tabindex]:not([tabindex="-1"])',
      );
      if (focusables.length === 0) return;
      const first = focusables[0];
      const last = focusables[focusables.length - 1];
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    };
    node.addEventListener("keydown", onKeydown);
    return {
      destroy() {
        node.removeEventListener("keydown", onKeydown);
        previouslyFocused?.focus();
      },
    };
  }
```
And then `use:trapFocus`. The suggestion_code field is a single snippet; I'll give a condensed version.

